async fn submit_eth_sign_request(
    contract: &eth::ChainSignaturesContract<eth::SandboxMiddleware>,
    requester: Address,
    chain_id: u64,
    seed: usize,
    path_prefix: &str,
) -> Result<SubmittedEthRequest> {
    let payload = [seed as u8; 32];
    let path = format!("{path_prefix}/{seed}");

    let request = eth::SignRequest {
        payload,
        path: path.clone(),
        key_version: LATEST_MPC_KEY_VERSION,
        algo: ETH_ALGO.to_string(),
        dest: ETH_DESTINATION.to_string(),
        params: ETH_PARAMS.to_string(),
    };

    let pending = contract.sign(request).value(U256::from(ETH_DEPOSIT_WEI)).send().await?;
    let receipt = pending.await?.context("sign transaction failed")?;
    let receipt_block = receipt
        .block_number
        .context("missing block number in sign receipt")?
        .as_u64();

    let request_id = eth::compute_request_id(
        requester,
        payload,
        &path,
        LATEST_MPC_KEY_VERSION,
        U256::from(chain_id),
        ETH_ALGO,
        ETH_DESTINATION,
        ETH_PARAMS,
    );

    Ok(SubmittedEthRequest {
        request_id,
        requester,
        receipt_block,
    })
}

async fn wait_for_all_responses(
    contract: &eth::ChainSignaturesContract<eth::SandboxMiddleware>,
    from_block: u64,
    submissions: &[SubmittedEthRequest],
    timeout: Duration,
) -> Result<()> {
    let expected = submissions
        .iter()
        .map(|submission| (submission.request_id, submission.requester))
        .collect::<std::collections::HashSet<_>>();

    tokio::time::timeout(timeout, async {
        loop {
            let mut observed = std::collections::HashSet::new();
            let events = contract
                .event::<eth::SignatureRespondedFilter>()
                .from_block(BlockNumber::Number(from_block.into()))
                .query()
                .await?;

            for event in events {
                observed.insert((H256::from_slice(event.request_id.as_ref()), event.responder));
            }

            if expected.is_subset(&observed) {
                return Ok(());
            }

            sleep(Duration::from_secs(1)).await;
        }
    })
    .await
    .map_err(|_| anyhow!("timed out waiting for ethereum responses after block {from_block}"))?
}

async fn assert_no_response_within(
    contract: &eth::ChainSignaturesContract<eth::SandboxMiddleware>,
    submission: &SubmittedEthRequest,
    wait_for: Duration,
) -> Result<()> {
    let started_at = Instant::now();
    while started_at.elapsed() < wait_for {
        let events = contract
            .event::<eth::SignatureRespondedFilter>()
            .from_block(BlockNumber::Number(submission.receipt_block.into()))
            .query()
            .await?;

        if events.into_iter().any(|event| {
            event.responder == submission.requester
                && event.request_id.as_ref() == submission.request_id.as_bytes()
        }) {
            anyhow::bail!(
                "observed ethereum response for {} before quorum was restored",
                hex::encode(submission.request_id)
            );
        }

        sleep(Duration::from_secs(1)).await;
    }

    Ok(())
}

async fn produce_empty_eth_blocks(
    client: &std::sync::Arc<eth::SandboxMiddleware>,
    block_count: u64,
) -> Result<()> {
    let sink = Address::from_low_u64_be(0xdead_beef);

    for _ in 0..block_count {
        let tx = TransactionRequest::new()
            .to(sink)
            .value(U256::zero())
            .gas(U256::from(21_000_u64));

        client
            .send_transaction(tx, None)
            .await?
            .await?
            .context("empty block-pumping transaction failed")?;
    }

    Ok(())
}

