    const DEFAULT_MNEMONIC: &'static str =
        "test test test test test test test test test test test junk";

    pub async fn run(spawner: &ClusterSpawner) -> anyhow::Result<Self> {
        let chain_id_arg = Self::DEFAULT_CHAIN_ID.to_string();
        let command = vec![
            "anvil".to_string(),
