    nodes.wait().nodes_resharing().await?;

    {
        let states = nodes.fetch_states().await?;
        for (account_id, state) in nodes.account_ids().into_iter().zip(states.iter()) {
            match state {
                StateView::Resharing { phase, .. } => {
